import type { DefaultTheme, UserConfig } from "vitepress";
import type { DynamsoftThemeConfig } from "./index.js";

export type { DynamsoftThemeConfig };

/**
 * Wrap a docs site's VitePress config with the fleet-wide Dynamsoft
 * defaults: versioned `base` from `themeConfig.docsRoot` + the
 * `DOCS_VERSION` environment variable, GitHub-style GFM alerts, nav-bar
 * banner conventions, local search, vue/vitepress dedupe, and
 * SSR-bundling of this theme. Site-provided values extend or override the
 * defaults. See config.js for details.
 */
export declare function defineDynamsoftConfig(
	config: UserConfig<DynamsoftThemeConfig>,
): UserConfig<DynamsoftThemeConfig>;

/**
 * Load the sidebar generated by typedoc-vitepress-theme for the fleet's
 * `api/` convention; empty before the first API-reference generation.
 */
export declare function loadApiSidebar(docsDir?: string): DefaultTheme.SidebarItem[];
